            char[][] nextGrid = new char[n][n];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    int liveNeighbors = 0;
                    for (int d = 0; d < 8; d++) {
                        int ni = i + dr[d];
                        int nj = j + dc[d];
                        if (ni >= 0 && ni < n && nj >= 0 && nj < n) {
                            if (grid[ni][nj] == '1') {
                                liveNeighbors++;
                            }
                        }
                    }

                    if (grid[i][j] == '1') {
                        if (liveNeighbors == 2 || liveNeighbors == 3) {
                            nextGrid[i][j] = '1';
                        } else {
                            nextGrid[i][j] = '0';
                        }
                    } else {
                        if (liveNeighbors == 3) {
                            nextGrid[i][j] = '1';
                        } else {
                            nextGrid[i][j] = '0';
                        }
                    }
                }
            }
            grid = nextGrid;
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            sb.append(grid[i]).append('\n');
        }
        System.out.print(sb.toString());
    }
}
